(7566058, 1213769, 65234, '<td valign="top">Very dark and moody.</td>', 'Very dark and moody.', '2018-04-15 14:06:59.000000', NULL, 1),
(7566059, 1213793, 65234, '<td valign="top">Looks staged, and in this challenge I don''t think that''s a good thing.</td>', 'Looks staged, and in this challenge I don''t think that''s a good thing.', '2018-04-15 14:08:02.000000', NULL, 1),
(7566060, 1213787, 65234, '<td valign="top">I love shots like this. There''s a lot going on way down in the grass.</td>', 'I love shots like this. There''s a lot going on way down in the grass.', '2018-04-15 14:08:45.000000', NULL, 1),
(7566061, 1213786, 65234, '<td valign="top">Oh, I just hate those things. I have a Sweetgum tree in my yard so I get a LOT of them. They''re the perfect size to get stuck in the pads of the dogs'' feet. But make for a reasonably interesting pattern here.</td>', 'Oh, I just hate those things. I have a Sweetgum tree in my yard so I get a LOT of them. They''re the perfect size to get stuck in the pads of the dogs'' feet. But make for a reasonably interesting pattern here.', '2018-04-15 14:10:41.000000', NULL, 1),
(7566062, 1213770, 65234, '<td valign="top">What a marvelous little scene you found!</td>', 'What a marvelous little scene you found!', '2018-04-15 14:11:53.000000', NULL, 1),
(7566063, 1213539, 65234, '<td valign="top">It seems to me they''ve been arranged by a human, which IMO goes against the spirit of the challenge. The pattern of flowers is not natural. They''re very pretty, though.</td>', 'It seems to me they''ve been arranged by a human, which IMO goes against the spirit of the challenge. The pattern of flowers is not natural. They''re very pretty, though.', '2018-04-15 14:15:01.000000', NULL, 1),
(7566064, 1213798, 65234, '<td valign="top">Frost is a reliable source of interesting patterns. Well-captured. My fave in the challenge.</td>', 'Frost is a reliable source of interesting patterns. Well-captured. My fave in the challenge.', '2018-04-15 14:16:58.000000', NULL, 1),
(7566065, 1213780, 65234, '<td valign="top">Ghostly.</td>', 'Ghostly.', '2018-04-15 14:17:17.000000', NULL, 1),
(7566066, 1213592, 65234, '<td valign="top">Well done. This is not always as easy as it looks like it should be. I tried this technique on several stands of trees (reflected in a lake and not) and never got anything usable.</td>', 'Well done. This is not always as easy as it looks like it should be. I tried this technique on several stands of trees (reflected in a lake and not) and never got anything usable.', '2018-04-15 14:18:53.000000', NULL, 1),
